const generateTokenMapping = ({ sharedTokenProps, chainIds }) => chainIds.reduce((acc, chainId) => {
	const token = {
		...sharedTokenProps,
		chainId
	};
	return {
		...acc,
		[chainId]: token
	};
}, {});
